const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const aoi = ee.Geometry.Point(45.2086, 4.7358).buffer(5000); // 5km buffer around a point on the Shebelle River near Beledweyne, Somalia

    const date1 = '2015-05-17';
    const date2 = '2018-05-09';
    const dateRange = 3; // +/- days to find a clear image

    // 2. Data Acquisition & Processing Function
    // Using Landsat 8 as it covers both dates.
    const getWaterArea = (date, range, geometry) => {
        const startDate = ee.Date(date).advance(-range, 'day');
        const endDate = ee.Date(date).advance(range, 'day');
        const collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
            .filterBounds(geometry)
            .filterDate(startDate, endDate)
            .sort('CLOUD_COVER'); // Get the least cloudy image first

        const size = collection.size().getInfo();
        if (size === 0) {
            return {
                area: null,
                count: size,
                cloud_percent: null
            };
        }

        const image = ee.Image(collection.first());

        // Cloud masking function for Landsat 8 C02
        const cloudMask = (img) => {
            const qa = img.select('QA_PIXEL');
            // Bits 3, 4, 5 are cloud shadow, snow, and cloud. We want clear conditions (bit 1 = 0, bit 2 = 0) and water (bit 7 = 1). Let's keep it simple: keep clear and water bits.
            // Clear is bit 1, Water is bit 7. We want pixels where clear is 1 (dilated cloud is 0, cirrus is 0, cloud is 0, cloud shadow is 0)
            const clear = qa.bitwiseAnd(1 << 1).neq(0); // Bit 1 is dilated cloud, we want clear so we should check another bit
            const cloud = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4)); // Cloud or cloud shadow
            return img.updateMask(cloud.not());
        };

        const maskedImage = cloudMask(image);

        // Calculate NDWI = (Green - NIR) / (Green + NIR)
        // L8 SR bands: B3(Green), B5(NIR)
        const ndwi = maskedImage.normalizedDifference(['SR_B3', 'SR_B5']).rename('ndwi');

        // Identify water pixels (a common threshold for NDWI)
        const waterMask = ndwi.gt(0);
        const waterImage = maskedImage.updateMask(waterMask);

        // Calculate the number of water pixels
        const waterPixelCount = waterImage.select('SR_B3').reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: geometry,
            scale: 30, // Landsat resolution
            maxPixels: 1e9
        }).get('SR_B3');

        // Calculate cloud percentage
        const cloudiness = ee.Number(image.get('CLOUD_COVER'));

        return {
            area: waterPixelCount,
            count: size,
            cloud_percent: cloudiness
        };
    };

    // 3. Calculation for both dates
    const result1_obj = getWaterArea(date1, dateRange, aoi);
    const result2_obj = getWaterArea(date2, dateRange, aoi);

    const count1 = result1_obj.count;
    const count2 = result2_obj.count;

    if (count1 === 0 || count2 === 0) {
        console.log(`Images found for 2015 period: ${count1}`);
        console.log(`Images found for 2018 period: ${count2}`);
        console.log('C1');
        return;
    }

    const area1 = ee.Number(result1_obj.area).getInfo();
    const area2 = ee.Number(result2_obj.area).getInfo();
    const cloud1 = result1_obj.cloud_percent.getInfo();
    const cloud2 = result2_obj.cloud_percent.getInfo();


    console.log(`Period 1 (2015-05-17 +/-${dateRange}d): Found ${count1} image(s). Cloud cover: ${cloud1.toFixed(2)}%`);
    console.log(`Period 2 (2018-05-09 +/-${dateRange}d): Found ${count2} image(s). Cloud cover: ${cloud2.toFixed(2)}%`);

    if (area1 === null || area2 === null) {
        console.log('Could not calculate water area for one or both periods.');
        console.log('C3');
        return;
    }

    if (area1 === 0 || area2 === 0) {
        console.log(`2015 Water Pixel Count: ${area1}`);
        console.log(`2018 Water Pixel Count: ${area2}`);
        console.log('No valid water pixels found after processing for one or both dates.');
        console.log('C2');
        return;
    }

    // 4. Validation & Final Answer
    console.log(`2015 Water Pixel Count: ${area1}`);
    console.log(`2018 Water Pixel Count: ${area2}`);

    if (area2 > area1) {
        console.log('Evidence: Water extent was greater in May 2018 than in May 2015.');
        console.log('A');
    } else {
        console.log('Evidence: Water extent was not greater in May 2018 than in May 2015.');
        console.log('B');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    console.log('D');
});
